def put(obj,key,value):
 keys=key.split('.');node=obj
 for k in keys[:-1]:node=node[k]
 node[keys[-1]]=copy.deepcopy(value)
def digest(path):return hashlib.sha256(pathlib.Path(path).read_bytes()).hexdigest()
